    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        //
        // spot rows carry the fields up to askQty, contract rows additionally carry
        // openInterest, fundingRate, nextFundingTime and fundingIntervalMinutes
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(ticker, "symbol");
        market = this.safeMarket(marketId, market);
        Object last = this.safeString(ticker, "lastPrice");
        Object baseVolume = this.safeString(ticker, "amount");
        if (Helpers.isTrue(Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(baseVolume, null))) && Helpers.isTrue((!Helpers.isEqual(market, null)))) && Helpers.isTrue(Helpers.GetValue(market, "contract"))))
        {
            // for contract markets the amount field is denominated in contracts, verified live -
            // scaling by contractSize converts it into base currency units
            Object contractSizeString = this.numberToString(Helpers.GetValue(market, "contractSize"));
            if (Helpers.isTrue(!Helpers.isEqual(contractSizeString, null)))
            {
                baseVolume = Precise.stringMul(baseVolume, contractSizeString);
            }
        }
        Object timestamp = this.safeTimestamp(ticker, "closeTime");
        final Object finalMarket = market;
        final Object finalBaseVolume = baseVolume;
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "symbol", BtseCore.this.safeSymbol(marketId, finalMarket) );
            put( "timestamp", timestamp );
            put( "datetime", BtseCore.this.iso8601(timestamp) );
            put( "high", BtseCore.this.safeString(ticker, "highPrice") );
            put( "low", BtseCore.this.safeString(ticker, "lowPrice") );
            put( "bid", BtseCore.this.safeString(ticker, "bidPrice") );
            put( "bidVolume", BtseCore.this.safeString(ticker, "bidQty") );
            put( "ask", BtseCore.this.safeString(ticker, "askPrice") );
            put( "askVolume", BtseCore.this.safeString(ticker, "askQty") );
            put( "vwap", null );
            put( "open", BtseCore.this.safeString(ticker, "openPrice") );
            put( "close", last );
            put( "last", last );
            put( "previousClose", BtseCore.this.safeString(ticker, "prevClosePrice") );
            put( "change", BtseCore.this.safeString(ticker, "priceChange") );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", finalBaseVolume );
            put( "quoteVolume", BtseCore.this.safeString(ticker, "volume") );
            put( "markPrice", null );
            put( "indexPrice", null );
            put( "info", ticker );
        }}, market);
    }

