    public Object parsePosition(Object position, Object... optionalArgs)
    {
        //
        //     {
        //         "marginType": 91,
        //         "entryPrice": 1968.78,
        //         "markPrice": 1967.47829431,
        //         "symbol": "ETH-PERP",
        //         "side": "BUY",
        //         "orderValue": 3.93495658,
        //         "settleWithAsset": "USDT",
        //         "unrealizedProfitLoss": -0.00260341,
        //         "totalMaintenanceMargin": 0.0218963,
        //         "size": 20,
        //         "liquidationPrice": 0,
        //         "isolatedLeverage": 25,
        //         "adlScoreBucket": 1,
        //         "contractSize": 0.0001,
        //         "liquidationInProgress": false,
        //         "timestamp": 1770880518034,
        //         "takeProfitOrder": {
        //             "orderId": "18b4056a-59de-424a-843e-c2df5c9f7265",
        //             "side": "SELL",
        //             "triggerPrice": 2500,
        //             "triggerUseLastPrice": false
        //         },
        //         "stopLossOrder": {
        //             "orderId": "e7ef1035-0773-446d-9a80-2de0e1de2c13",
        //             "side": "SELL",
        //             "triggerPrice": 1000,
        //             "triggerUseLastPrice": false
        //         },
        //         "positionMode": "ONE_WAY",
        //         "positionDirection": null,
        //         "positionId": "ETH-PERP-USDT",
        //         "walletName": "CROSS@",
        //         "currentLeverage": 0.2,
        //         "minimumRequiredMargin": 0
        //     }
        //
        // rows echo the short symbol form, while positionId carries the full market
        // id, optionally suffixed with the isolated wallet discriminator after a pipe
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(position, "positionId");
        if (Helpers.isTrue(!Helpers.isEqual(marketId, null)))
        {
            Object parts = Helpers.split(marketId, "|");
            marketId = this.safeString(parts, 0);
        } else
        {
            marketId = this.safeString(position, "symbol");
        }
        market = this.safeMarket(marketId, market);
        Object timestamp = this.safeInteger(position, "timestamp");
        Object marginType = this.safeString(position, "marginType");
        Object side = this.safeStringLower2(position, "positionDirection", "side");
        Object positionMode = this.safeString(position, "positionMode");
        Object hedged = Helpers.isTrue((Helpers.isEqual(positionMode, "HEDGE"))) || Helpers.isTrue((Helpers.isEqual(positionMode, "ISOLATED")));
        Object takeProfitOrder = this.safeDict(position, "takeProfitOrder", new java.util.HashMap<String, Object>() {{}});
        Object takeProfitPrice = this.safeString(takeProfitOrder, "triggerPrice");
        Object stopLossOrder = this.safeDict(position, "stopLossOrder", new java.util.HashMap<String, Object>() {{}});
        Object stopLossPrice = this.safeString(stopLossOrder, "triggerPrice");
        final Object finalMarket = market;
        return this.safePosition(new java.util.HashMap<String, Object>() {{
            put( "info", position );
            put( "id", BtseCore.this.safeString(position, "positionId") );
            put( "symbol", Helpers.GetValue(finalMarket, "symbol") );
            put( "entryPrice", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "entryPrice")) );
            put( "markPrice", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "markPrice")) );
            put( "lastPrice", null );
            put( "takeProfitPrice", BtseCore.this.parseNumber(takeProfitPrice) );
            put( "stopLossPrice", BtseCore.this.parseNumber(stopLossPrice) );
            put( "notional", BtseCore.this.parseNumber(BtseCore.this.safeString2(position, "notionalValue", "orderValue")) );
            put( "collateral", null );
            put( "unrealizedPnl", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "unrealizedProfitLoss")) );
            put( "realizedPnl", null );
            put( "side", BtseCore.this.parsePositionSide(side) );
            put( "contracts", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "size")) );
            put( "contractSize", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "contractSize")) );
            put( "timestamp", timestamp );
            put( "datetime", BtseCore.this.iso8601(timestamp) );
            put( "lastUpdateTimestamp", null );
            put( "hedged", hedged );
            put( "maintenanceMargin", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "totalMaintenanceMargin")) );
            put( "maintenanceMarginPercentage", null );
            put( "initialMargin", null );
            put( "initialMarginPercentage", null );
            put( "leverage", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "currentLeverage")) );
            put( "liquidationPrice", BtseCore.this.parseNumber(BtseCore.this.safeString(position, "liquidationPrice")) );
            put( "marginRatio", null );
            put( "marginMode", BtseCore.this.parseMarginModeType(marginType) );
            put( "percentage", null );
        }});
    }

